import subprocess, os, json, glob, sys, tempfile, shutil
EXE="/workspace/executable"
def run(seed, w, h, botmoves, names=None, extra=None, nplayers=None, timeout=300, keep=False):
    d=tempfile.mkdtemp(dir="/tmp/cb")
    args=[EXE,"-d",f"{w} {h}","-s",str(seed),"-q","-t","-i",d]
    if extra: args+=extra
    if nplayers: args+=["-n",str(nplayers)]
    for i,mv in enumerate(botmoves):
        p=os.path.join(d,f"s{i}.json"); json.dump(mv,open(p,"w"))
        nm = names[i] if names else f"B{i+1}"
        args.append(f"env SCRIPT={p} BOTNAME={nm} python3 /workspace/probe/scriptbot.py")
    r=subprocess.run(args,capture_output=True,cwd=d,timeout=timeout,text=True)
    files=glob.glob(os.path.join(d,"*.hlt"))
    rep=json.load(open(sorted(files)[0])) if files else None
    logs={os.path.basename(f):open(f).read() for f in glob.glob(os.path.join(d,"*.log"))}
    if not keep: shutil.rmtree(d)
    return r.stdout, r.stderr, rep, logs

def show(rep, frames=None, prod=False):
    W,H=rep['width'],rep['height']
    n=len(rep['frames'])
    if prod:
        print("PROD");
        for r in range(H): print(" ".join(f"{x:2d}" for x in rep['productions'][r]))
    idxs = frames if frames is not None else range(n)
    for i in idxs:
        if i<0: i=n+i
        if i>=n: break
        print(f"--- frame {i} ---")
        for r in range(H):
            print(" ".join(f"{c[0]}:{c[1]:3d}" for c in rep['frames'][i][r]))
        if i < len(rep['moves']):
            print("  moves:")
            for r in range(H):
                print("   ", " ".join(str(x) for x in rep['moves'][i][r]))
