CAP=255
DR=[0,-1,0,1,0]; DC=[0,0,1,0,-1]

def step(owner, strength, prod, moves, nplayers, cap=CAP, prod_cap=True):
    """owner,strength,prod,moves: HxW lists. moves[r][c] in 0..4 (0=still)."""
    H=len(owner); W=len(owner[0])
    # pieces[(p,(r,c))] = strength ; presence matters even at 0
    pieces={}
    def add(p,rc,s):
        pieces[(p,rc)] = pieces.get((p,rc),0) + s
    for r in range(H):
        for c in range(W):
            p=owner[r][c]
            if p==0: continue
            d=moves[r][c]
            if d==0:
                s=strength[r][c]+prod[r][c]
                if prod_cap and s>cap: s=cap
                add(p,(r,c),s)
            else:
                nr=(r+DR[d])%H; nc=(c+DC[d])%W
                add(p,(nr,nc),strength[r][c])
                add(p,(r,c),0)   # vacated site still belongs to p with strength 0
    for k in list(pieces):
        if pieces[k]>cap: pieces[k]=cap
    # per-cell aggregation
    cellp={}
    for (p,rc),s in pieces.items():
        cellp.setdefault(rc,{})[p]=s
    no=[[0]*W for _ in range(H)]; ns=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            neutral = strength[r][c] if owner[r][c]==0 else 0
            here = cellp.get((r,c),{})
            # damage
            surv=None
            for p,s in here.items():
                dmg = neutral
                for q,t in here.items():
                    if q!=p: dmg+=t
                for d in (1,2,3,4):
                    nr=(r+DR[d])%H; nc=(c+DC[d])%W
                    for q,t in cellp.get((nr,nc),{}).items():
                        if q!=p: dmg+=t
                rem = s-dmg
                if rem>0 or dmg==0:
                    if surv is None or (rem> surv[1]):
                        surv=(p, max(rem,0))
            if surv is not None:
                no[r][c]=surv[0]; ns[r][c]=min(surv[1],cap)
            else:
                tot=sum(here.values())
                no[r][c]=0; ns[r][c]=max(0, neutral-tot)
    return no, ns
