cat > /tmp/cb/model2.py <<'PYEOF'
DR=[0,-1,0,1,0]; DC=[0,0,1,0,-1]
DEF=dict(cap=255, prod_before_combat=True, prod_cap=True, merge_cap='clamp',
         self_site=True, neighbors=True, neutral_self=True, neutral_neighbors=False,
         kill='ge_presence', vacated_piece=True, cap_before_damage=True, diag=False)
def step(owner, strength, prod, moves, nplayers, **o):
    P=dict(DEF); P.update(o); cap=P['cap']
    H=len(owner); W=len(owner[0])
    pieces={}
    def add(p,rc,s):
        d=pieces.setdefault(rc,{}); d[p]=d.get(p,0)+s
    for r in range(H):
        for c in range(W):
            p=owner[r][c]
            if p==0: continue
            d=moves[r][c]
            if d==0:
                s=strength[r][c]+(prod[r][c] if P['prod_before_combat'] else 0)
                if P['prod_cap'] and s>cap: s=cap
                add(p,(r,c),s)
            else:
                nr=(r+DR[d])%H; nc=(c+DC[d])%W
                add(p,(nr,nc),strength[r][c])
                if P['vacated_piece']: add(p,(r,c),0)
    if P['cap_before_damage']:
        for rc in pieces:
            for p in pieces[rc]:
                v=pieces[rc][p]
                if v>cap:
                    pieces[rc][p]= cap if P['merge_cap']=='clamp' else (v & 0xFF)
    dirs=[]
    if P['neighbors']: dirs=[1,2,3,4]
    diag=[(-1,-1),(-1,1),(1,-1),(1,1)] if P['diag'] else []
    no=[[0]*W for _ in range(H)]; ns=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            neutral = strength[r][c] if owner[r][c]==0 else 0
            here = pieces.get((r,c),{})
            winner=None
            for p,s in here.items():
                inj=0; has=False
                if P['neutral_self'] and neutral>0: inj+=neutral; has=True
                if P['self_site']:
                    for q,t in here.items():
                        if q!=p: inj+=t; has=True
                for d in dirs:
                    nr=(r+DR[d])%H; nc=(c+DC[d])%W
                    if P['neutral_neighbors'] and owner[nr][nc]==0 and strength[nr][nc]>0:
                        inj+=strength[nr][nc]; has=True
                    for q,t in pieces.get((nr,nc),{}).items():
                        if q!=p: inj+=t; has=True
                for dr,dc in diag:
                    nr=(r+dr)%H; nc=(c+dc)%W
                    for q,t in pieces.get((nr,nc),{}).items():
                        if q!=p: inj+=t; has=True
                dead=False
                if P['kill']=='ge_presence': dead = has and inj>=s
                elif P['kill']=='ge_always': dead = inj>=s
                elif P['kill']=='gt': dead = inj>s
                elif P['kill']=='ge_dmgpos': dead = inj>0 and inj>=s
                if dead: continue
                rem=s-inj
                if winner is None or rem>winner[1]: winner=(p,rem)
            if winner is not None:
                v=max(winner[1],0)
                no[r][c]=winner[0]; ns[r][c]=min(v,cap)
            else:
                tot=sum(here.values())
                no[r][c]=0; ns[r][c]=max(0,neutral-tot)
            if not P['prod_before_combat'] and no[r][c]!=0 and moves[r][c]==0 and owner[r][c]==no[r][c]:
                ns[r][c]=min(cap, ns[r][c]+prod[r][c])
    return no, ns
